CREATE TABLE school_records (id text PRIMARY KEY, org_id text NOT NULL, branch_id text NOT NULL, class_id text, student_id text, created_by text NOT NULL, kind text NOT NULL CHECK(kind IN ('material','lesson_plan','exam','calendar','discipline','complaint','meeting','teacher_review','vendor','expense','payroll','reconciliation','certificate','principal_report','timetable')), title text NOT NULL, data jsonb NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','submitted','changes_requested','approved','published','rejected','archived','reconciled','paid_external')), revision integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(org_id,id), FOREIGN KEY(org_id,branch_id) REFERENCES branches(org_id,id), FOREIGN KEY(org_id,class_id) REFERENCES classes(org_id,id), FOREIGN KEY(org_id,student_id) REFERENCES students(org_id,id), FOREIGN KEY(org_id,created_by) REFERENCES users(org_id,id));
CREATE INDEX school_records_scope ON school_records(org_id,branch_id,kind,status);
CREATE TABLE backup_records (id text PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now(), encrypted_sha256 text NOT NULL, bytes bigint NOT NULL CHECK(bytes>0), status text NOT NULL CHECK(status IN ('created','restore_verified')), note text NOT NULL);
CREATE FUNCTION prevent_audit_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Audit history is append-only'; END $$;
CREATE TRIGGER protect_audit_history BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION prevent_audit_mutation();
